import{_ as s,o as t,c as n,a as r}from"./app.DkoUFz-u.js";const _=JSON.parse('{"title":"MySQL高可用架构（MHA与Orchestrator）深度解析学习笔记","description":"","frontmatter":{},"headers":[],"relativePath":"data/database/relational/mysql/high-availability.md","filePath":"data/database/relational/mysql/high-availability.md"}'),e={name:"data/database/relational/mysql/high-availability.md"};function i(l,a,o,h,d,p){return t(),n("div",null,[...a[0]||(a[0]=[r(`<h1 id="mysql高可用架构-mha与orchestrator-深度解析学习笔记" tabindex="-1">MySQL高可用架构（MHA与Orchestrator）深度解析学习笔记 <a class="header-anchor" href="#mysql高可用架构-mha与orchestrator-深度解析学习笔记" aria-label="Permalink to &quot;MySQL高可用架构（MHA与Orchestrator）深度解析学习笔记&quot;">​</a></h1><h2 id="一、高可用基础概念" tabindex="-1">一、高可用基础概念 <a class="header-anchor" href="#一、高可用基础概念" aria-label="Permalink to &quot;一、高可用基础概念&quot;">​</a></h2><h4 id="_1-核心目标" tabindex="-1">1. <strong>核心目标</strong> <a class="header-anchor" href="#_1-核心目标" aria-label="Permalink to &quot;1. **核心目标**&quot;">​</a></h4><ul><li><strong>RTO（恢复时间目标）</strong>：故障后恢复服务的耗时（MHA：10–30秒；Orchestrator：3–10秒）</li><li><strong>RPO（数据丢失容忍度）</strong>：故障时允许丢失的数据量（通过GTID/半同步复制降低风险）</li><li><strong>自动化程度</strong>：故障检测、切换、拓扑修复的自动化能力</li></ul><h4 id="_2-核心依赖技术" tabindex="-1">2. <strong>核心依赖技术</strong> <a class="header-anchor" href="#_2-核心依赖技术" aria-label="Permalink to &quot;2. **核心依赖技术**&quot;">​</a></h4><table tabindex="0"><thead><tr><th><strong>技术</strong></th><th><strong>作用</strong></th></tr></thead><tbody><tr><td>主从复制</td><td>数据同步基础（异步/半同步/GTID）</td></tr><tr><td>虚拟IP（VIP）</td><td>应用无感知切换（需配合Keepalived）</td></tr><tr><td>多节点探活</td><td>防止脑裂（如Orchestrator的多路径检测）</td></tr></tbody></table><hr><h2 id="二、mha-master-high-availability-深度解析" tabindex="-1">二、MHA（Master High Availability）深度解析 <a class="header-anchor" href="#二、mha-master-high-availability-深度解析" aria-label="Permalink to &quot;二、MHA（Master High Availability）深度解析&quot;">​</a></h2><h4 id="_1-核心架构" tabindex="-1">1. <strong>核心架构</strong> <a class="header-anchor" href="#_1-核心架构" aria-label="Permalink to &quot;1. **核心架构**&quot;">​</a></h4><table tabindex="0"><thead><tr><th><strong>组件</strong></th><th><strong>角色</strong></th></tr></thead><tbody><tr><td><strong>Manager节点</strong></td><td>监控Master，执行故障切换（通过<code>masterha_manager</code>）</td></tr><tr><td><strong>Node节点</strong></td><td>部署在每台MySQL服务器，执行日志保存、差异修复（如<code>save_binary_logs</code>）</td></tr><tr><td><strong>自定义脚本</strong></td><td>扩展功能（VIP切换、邮件告警）</td></tr></tbody></table><h4 id="_2-故障转移流程" tabindex="-1">2. <strong>故障转移流程</strong> <a class="header-anchor" href="#_2-故障转移流程" aria-label="Permalink to &quot;2. **故障转移流程**&quot;">​</a></h4><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_140thh">graph TD</span></span>
<span class="line"><span class="__shiki_140thh">    A[Master宕机] --&gt; B[Manager检测故障&lt;br&gt;（9–12秒）]</span></span>
<span class="line"><span class="__shiki_140thh">    B --&gt; C[选举最新Slave&lt;br&gt;（基于Binlog位置）]</span></span>
<span class="line"><span class="__shiki_140thh">    C --&gt; D[应用差异日志&lt;br&gt;（并行修复其他Slave）]</span></span>
<span class="line"><span class="__shiki_140thh">    D --&gt; E[提升新Master]</span></span>
<span class="line"><span class="__shiki_140thh">    E --&gt; F[VIP漂移&lt;br&gt;（脚本触发）]</span></span></code></pre></div><h4 id="_3-核心优势" tabindex="-1">3. <strong>核心优势</strong> <a class="header-anchor" href="#_3-核心优势" aria-label="Permalink to &quot;3. **核心优势**&quot;">​</a></h4><ul><li><strong>数据一致性保障</strong>：从最新Slave拉取差异日志修复其他节点</li><li><strong>兼容性广</strong>：支持所有MySQL存储引擎（InnoDB/MyISAM）</li><li><strong>无侵入性</strong>：无需修改MySQL配置</li></ul><h4 id="_4-部署实践" tabindex="-1">4. <strong>部署实践</strong> <a class="header-anchor" href="#_4-部署实践" aria-label="Permalink to &quot;4. **部署实践**&quot;">​</a></h4><p><strong>关键步骤：</strong></p><ol><li><strong>SSH免密配置</strong>：Manager到所有Node的免密访问</li><li><strong>复制用户创建</strong>：<code>GRANT REPLICATION SLAVE ON *.* TO &#39;repl&#39;@&#39;%&#39;</code></li><li><strong>配置文件示例</strong>（<code>/etc/mha/app1.cnf</code>）：<div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_1t8gfj">[server default]</span></span>
<span class="line"><span class="__shiki_1itgoe">manager_workdir</span><span class="__shiki_140thh">=/var/log/mha/app1</span></span>
<span class="line"><span class="__shiki_1itgoe">master_ip_failover_script</span><span class="__shiki_140thh">=/scripts/vip_switch.sh</span></span>
<span class="line"><span class="__shiki_1itgoe">ssh_user</span><span class="__shiki_140thh">=root</span></span>
<span class="line"></span>
<span class="line"><span class="__shiki_1t8gfj">[server1]</span></span>
<span class="line"><span class="__shiki_1itgoe">hostname</span><span class="__shiki_140thh">=master_ip</span></span>
<span class="line"><span class="__shiki_1itgoe">candidate_master</span><span class="__shiki_140thh">=1</span></span>
<span class="line"></span>
<span class="line"><span class="__shiki_1t8gfj">[server2]</span></span>
<span class="line"><span class="__shiki_1itgoe">hostname</span><span class="__shiki_140thh">=slave1_ip</span></span>
<span class="line"><span class="__shiki_1itgoe">no_master</span><span class="__shiki_140thh">=1</span></span></code></pre></div></li></ol><h4 id="_5-局限与挑战" tabindex="-1">5. <strong>局限与挑战</strong> <a class="header-anchor" href="#_5-局限与挑战" aria-label="Permalink to &quot;5. **局限与挑战**&quot;">​</a></h4><ul><li><strong>Manager单点故障</strong>：需额外部署多Manager或结合Pacemaker</li><li><strong>从库监控缺失</strong>：不监控复制延迟/中断</li><li><strong>VIP依赖脚本</strong>：需自定义<code>master_ip_failover_script</code></li></ul><hr><h2 id="三、orchestrator架构解析" tabindex="-1">三、Orchestrator架构解析 <a class="header-anchor" href="#三、orchestrator架构解析" aria-label="Permalink to &quot;三、Orchestrator架构解析&quot;">​</a></h2><h4 id="_1-核心特性" tabindex="-1">1. <strong>核心特性</strong> <a class="header-anchor" href="#_1-核心特性" aria-label="Permalink to &quot;1. **核心特性**&quot;">​</a></h4><table tabindex="0"><thead><tr><th><strong>特性</strong></th><th><strong>说明</strong></th></tr></thead><tbody><tr><td><strong>拓扑自动发现</strong></td><td>动态映射主从关系（Web界面可视化）</td></tr><tr><td><strong>Raft协议</strong></td><td>自身高可用（3节点防单点故障）</td></tr><tr><td><strong>精准故障模型</strong></td><td>支持30+故障类型（如<code>DeadMaster</code>）</td></tr></tbody></table><h4 id="_2-故障恢复流程-deadmaster场景" tabindex="-1">2. <strong>故障恢复流程（DeadMaster场景）</strong> <a class="header-anchor" href="#_2-故障恢复流程-deadmaster场景" aria-label="Permalink to &quot;2. **故障恢复流程（DeadMaster场景）**&quot;">​</a></h4><ol><li><strong>检测阶段</strong>（1秒/次）：连接失败 + 所有Slave复制中断</li><li><strong>选主逻辑</strong>： <ul><li>同数据中心优先</li><li>Binlog格式兼容性检查（ROW &gt; MIXED）</li><li>复制延迟阈值过滤（默认60秒）</li></ul></li><li><strong>切换动作</strong>： <ul><li>调用<code>PreFailoverProcesses</code>钩子</li><li>提升新Master：<code>STOP SLAVE; RESET SLAVE ALL; SET GLOBAL read_only=OFF;</code></li><li>旧主打标签隔离</li></ul></li></ol><h4 id="_3-部署模式对比" tabindex="-1">3. <strong>部署模式对比</strong> <a class="header-anchor" href="#_3-部署模式对比" aria-label="Permalink to &quot;3. **部署模式对比**&quot;">​</a></h4><table tabindex="0"><thead><tr><th><strong>模式</strong></th><th><strong>适用场景</strong></th><th><strong>高可用保障</strong></th></tr></thead><tbody><tr><td>单点模式</td><td>测试环境</td><td>无</td></tr><tr><td>多点共享后端（MySQL）</td><td>单数据中心</td><td>Orchestrator高可用，后端单点</td></tr><tr><td>多点非共享后端（Raft）</td><td>跨数据中心生产环境</td><td>全组件高可用</td></tr></tbody></table><h4 id="_4-配置示例" tabindex="-1">4. <strong>配置示例</strong> <a class="header-anchor" href="#_4-配置示例" aria-label="Permalink to &quot;4. **配置示例**&quot;">​</a></h4><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_21nrsd"># orchestrator.conf.json</span></span>
<span class="line"><span class="__shiki_140thh">{</span></span>
<span class="line"><span class="__shiki_mdbnqw">  &quot;RaftEnabled&quot;</span><span class="__shiki_140thh">: </span><span class="__shiki_dzsirb">true</span><span class="__shiki_140thh">,</span></span>
<span class="line"><span class="__shiki_mdbnqw">  &quot;RaftDataDir&quot;</span><span class="__shiki_140thh">: </span><span class="__shiki_mdbnqw">&quot;/var/lib/orchestrator&quot;</span><span class="__shiki_140thh">,</span></span>
<span class="line"><span class="__shiki_mdbnqw">  &quot;MySQLTopologyUser&quot;</span><span class="__shiki_140thh">: </span><span class="__shiki_mdbnqw">&quot;orc_user&quot;</span><span class="__shiki_140thh">,</span></span>
<span class="line"><span class="__shiki_mdbnqw">  &quot;MySQLTopologyPassword&quot;</span><span class="__shiki_140thh">: </span><span class="__shiki_mdbnqw">&quot;orc_password&quot;</span><span class="__shiki_140thh">,</span></span>
<span class="line"><span class="__shiki_mdbnqw">  &quot;PromotionIgnoreHostnameFilters&quot;</span><span class="__shiki_140thh">: [</span><span class="__shiki_mdbnqw">&quot;backup.*&quot;</span><span class="__shiki_140thh">]</span></span>
<span class="line"><span class="__shiki_140thh">}</span></span></code></pre></div><hr><h2 id="四、mha-vs-orchestrator对比选型" tabindex="-1">四、MHA vs Orchestrator对比选型 <a class="header-anchor" href="#四、mha-vs-orchestrator对比选型" aria-label="Permalink to &quot;四、MHA vs Orchestrator对比选型&quot;">​</a></h2><table tabindex="0"><thead><tr><th><strong>维度</strong></th><th><strong>MHA</strong></th><th><strong>Orchestrator</strong></th></tr></thead><tbody><tr><td><strong>故障切换速度</strong></td><td>10–30秒</td><td>3–10秒</td></tr><tr><td><strong>数据一致性</strong></td><td>中（依赖日志补齐）</td><td>高（GTID优先）</td></tr><tr><td><strong>管理界面</strong></td><td>命令行</td><td>Web UI + API</td></tr><tr><td><strong>自身高可用</strong></td><td>需第三方工具（如Pacemaker）</td><td>内置Raft协议</td></tr><tr><td><strong>拓扑灵活性</strong></td><td>静态配置</td><td>动态重塑（拖拽调整）</td></tr><tr><td><strong>适用场景</strong></td><td>传统主从架构</td><td>云环境/多数据中心</td></tr></tbody></table><hr><h2 id="五、企业级实践建议" tabindex="-1">五、企业级实践建议 <a class="header-anchor" href="#五、企业级实践建议" aria-label="Permalink to &quot;五、企业级实践建议&quot;">​</a></h2><h4 id="_1-高可用架构选型" tabindex="-1">1. <strong>高可用架构选型</strong> <a class="header-anchor" href="#_1-高可用架构选型" aria-label="Permalink to &quot;1. **高可用架构选型**&quot;">​</a></h4><ul><li><strong>传统环境选MHA</strong>：已有主从复制 + Perl技术栈</li><li><strong>云原生/多DC选Orchestrator</strong>：需跨机房容灾 + 自动化拓扑管理</li></ul><h4 id="_2-增强数据安全" tabindex="-1">2. <strong>增强数据安全</strong> <a class="header-anchor" href="#_2-增强数据安全" aria-label="Permalink to &quot;2. **增强数据安全**&quot;">​</a></h4><ul><li><strong>GTID+半同步复制</strong>：避免数据丢失（<code>rpl_semi_sync_master_timeout=1000</code>）</li><li><strong>备份策略</strong>：每日全备 + Binlog保留（<code>mydumper</code> + <code>binlog-server</code>）</li></ul><h4 id="_3-监控与告警整合" tabindex="-1">3. <strong>监控与告警整合</strong> <a class="header-anchor" href="#_3-监控与告警整合" aria-label="Permalink to &quot;3. **监控与告警整合**&quot;">​</a></h4><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_140thh">graph LR</span></span>
<span class="line"><span class="__shiki_140thh">    A[MySQL Exporter] --&gt;|指标| B(Prometheus)</span></span>
<span class="line"><span class="__shiki_140thh">    B --&gt; C{Grafana}</span></span>
<span class="line"><span class="__shiki_140thh">    C --&gt; D[仪表盘]</span></span>
<span class="line"><span class="__shiki_140thh">    D --&gt;|告警| E[Alertmanager → 钉钉/邮件]</span></span></code></pre></div><h4 id="_4-常见避坑指南" tabindex="-1">4. <strong>常见避坑指南</strong> <a class="header-anchor" href="#_4-常见避坑指南" aria-label="Permalink to &quot;4. **常见避坑指南**&quot;">​</a></h4><ul><li><strong>MHA</strong>：避免长事务阻塞日志补齐（设<code>innodb_lock_wait_timeout=10</code>）</li><li><strong>Orchestrator</strong>：禁用跨数据中心切换（配置<code>RecoverCrossDataCenter=false</code>）</li><li><strong>通用</strong>：定期清理中继日志（<code>purge_relay_logs</code>脚本）</li></ul><hr><h2 id="六、进阶-混合架构设计" tabindex="-1">六、进阶：混合架构设计 <a class="header-anchor" href="#六、进阶-混合架构设计" aria-label="Permalink to &quot;六、进阶：混合架构设计&quot;">​</a></h2><p><strong>MHA+Orchestrator双保险架构：</strong></p><ol><li><strong>数据层</strong>：MHA处理快速故障切换</li><li><strong>控制层</strong>：Orchestrator监控拓扑一致性</li><li><strong>代理层</strong>：ProxySQL实现读写分离 + 连接池管理</li></ol><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_wvjl67">App → ProxySQL → MHA-Managed Cluster</span></span>
<span class="line"><span class="__shiki_wvjl67">               ↘ Orchestrator（监控+API干预）</span></span></code></pre></div><blockquote><p><strong>学习路径推荐</strong>：</p><ol><li>实验部署： <ul><li>MHA：<a href="https://github.com/yoshinorim/mha4mysql-manager" target="_blank" rel="noreferrer">GitHub官方文档</a></li><li>Orchestrator：<a href="https://github.com/openark/orchestrator" target="_blank" rel="noreferrer">快速入门指南</a></li></ul></li><li>故障模拟： <ul><li>使用<code>kill -9</code>模拟Master宕机</li><li>注入网络分区（<code>iptables DROP</code>）</li></ul></li><li>生产验证： <ul><li>sysbench压测 + 手动切换验证</li></ul></li></ol></blockquote>`,48)])])}const g=s(e,[["render",i]]);export{_ as __pageData,g as default};
